import java.io.BufferedWriter;
import java.io.StringWriter;

class FlushBoundary {
    public static void main(String[] args) throws Exception {
        var destination = new StringWriter();
        try (var writer = new BufferedWriter(destination)) {
            writer.write("PING");
            writer.newLine();
            writer.flush(); // message boundary; writer remains open
            System.out.print(destination.toString());
        }
    }
}
